R=/scratch/jjyeung/orch_n30
date -u +%TZ
mkdir -p $R/sb_rkdocs/prompts $R/sb_rkdocs/out
echo  | base64 -d > $R/sb_rkdocs/prompts/sb_rkdocs.md
mkdir -p $R/sb_nonnull/prompts $R/sb_nonnull/out
echo  | base64 -d > $R/sb_nonnull/prompts/sb_nonnull.md
