{ head -1 $R/sb_queue/queue.txt; echo sb_rkdocs; echo sb_nonnull; tail -n +2 $R/sb_queue/queue.txt; echo sb_cntfix; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt; cat $R/sb_queue/queue.txt | tr "\n" " "; echo; tail -1 $R/sb_queue/codexq.log
